pthread_t tid;
int param = 42;

// Routine signature: void *(*start_routine) (void *)
void *worker_routine(void *arg) {
    int *data = (int *)arg;
    // Thread logic...
    return NULL;
}

// Function: pthread_create(tid, attr, start_routine, arg)
int status = pthread_create(
    &tid,               // Output ID
    NULL,               // Attributes (Default)
    &worker_routine,    // Function pointer
    (void *)&param      // Argument pointer
);

if (status == 0) {
    // Wait for thread termination
    pthread_join(tid, NULL);
}
